    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} তারিখে পজিটিভ টেস্ট: খুব সম্ভবত কাল ওভুলেশন হবে। আজ ও কাল তোমার সবচেয়ে উর্বর দিন! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "তোমার টেস্ট অনুযায়ী সম্ভবত আজ ওভুলেশন হচ্ছে। তোমার সবচেয়ে উর্বর দিন! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "তোমার টেস্ট অনুযায়ী সম্ভবত {} তারিখে ওভুলেশন হয়েছে। তারিখগুলো ঠিক করে দিয়েছি 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "{} তারিখে LH পিক: খুব সম্ভবত আগামী ২৪–৩৬ ঘণ্টায় ওভুলেশন হবে। এগুলো তোমার সবচেয়ে উর্বর দিন! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "{} তারিখে পজিটিভ টেস্ট: ওভুলেশন খুব কাছে। সবচেয়ে উর্বর দিন আজ ও কাল 🌱",
