    "Al despertar, antes de levantarte, hablar o beber, y siempre a la misma hora. Después de ovular sube unos 0,3 °C y se queda alta hasta la regla.": "ঘুম ভাঙার পরই, ওঠা, কথা বলা বা কিছু খাওয়ার আগে, সবসময় একই সময়ে। ওভুলেশনের পর প্রায় ০.৩ °C বাড়ে এবং পিরিয়ড পর্যন্ত বেশি থাকে।",
