    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "LH-Spitze am {}: Du wirst sehr wahrscheinlich in den nächsten 24–36 Stunden ovulieren. Das sind deine fruchtbarsten Tage! 🌱",
