    "Premium: te avisamos cuando tu test de ovulación o tu temperatura indican que vas a ovular.": "Premium: σε ειδοποιούμε όταν το τεστ ωορρηξίας ή η θερμοκρασία δείχνουν ότι πλησιάζει η ωορρηξία.",
