    "Verificación": "Επαλήθευση",
    "Pico de LH el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "Κορυφή LH στις {}: πιθανότατα θα έχεις ωορρηξία αύριο. Σήμερα και αύριο είναι οι πιο γόνιμες μέρες σου! 🌱",
    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "Θετικό τεστ στις {}: πιθανότατα θα έχεις ωορρηξία αύριο. Σήμερα και αύριο είναι οι πιο γόνιμες μέρες σου! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "Σύμφωνα με το τεστ σου, πιθανότατα έχεις ωορρηξία σήμερα. Η πιο γόνιμη μέρα σου! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "Σύμφωνα με το τεστ σου, πιθανότατα είχες ωορρηξία στις {}. Προσαρμόσαμε τις ημερομηνίες σου 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "Κορυφή LH στις {}: πιθανότατα θα έχεις ωορρηξία μέσα σε 24–36 ώρες. Είναι οι πιο γόνιμες μέρες σου! 🌱",
