    "Al despertar, antes de levantarte, hablar o beber, y siempre a la misma hora. Después de ovular sube unos 0,3 °C y se queda alta hasta la regla.": "Μόλις ξυπνήσεις, πριν σηκωθείς, μιλήσεις ή πιεις, και πάντα την ίδια ώρα. Μετά την ωορρηξία ανεβαίνει περίπου 0,3 °C και μένει ψηλά μέχρι την περίοδο.",
