    "Última copia: {}": "Τελευταίο αντίγραφο: {}",
    "Si cambias de móvil, entra con esta misma cuenta y lo recuperas todo.": "Αν αλλάξεις κινητό, μπες με τον ίδιο λογαριασμό και τα παίρνεις όλα πίσω.",
