    "Premium: historial completo de tus ciclos, síntomas y estado de ánimo.": "પ્રીમિયમ: તમારા ચક્ર, લક્ષણો અને મૂડનો પૂરો ઇતિહાસ.",
    "Premium: toca una tendencia para ver su detalle de 8 semanas.": "પ્રીમિયમ: 8 અઠવાડિયાની વિગત જોવા વલણ પર ટેપ કરો.",
    "Premium: más ropa para Michi 👑": "પ્રીમિયમ: મિચી માટે વધુ કપડાં 👑",
    "Premium: te avisamos cuando tu test de ovulación o tu temperatura indican que vas a ovular.": "પ્રીમિયમ: ઓવ્યુલેશન ટેસ્ટ કે તાપમાન બતાવે કે ઓવ્યુલેશન નજીક છે ત્યારે અમે જાણ કરીશું.",
    "Retos de Michi": "મિચીની ચેલેન્જ",
