    "Informe completo para tu médico": "ડૉક્ટર માટે પૂરો રિપોર્ટ",
    "Avisos de fertilidad: temperatura y test de ovulación": "ફળદ્રુપતા સૂચનાઓ: તાપમાન અને ઓવ્યુલેશન ટેસ્ટ",
    "Armario, retos y logros de Michi": "મિચીનો કબાટ, ચેલેન્જ અને બેજ",
    "Esto es Premium 👑": "આ પ્રીમિયમ છે 👑",
    "Lo básico de CicloPlus es gratis para siempre. Con Premium, además:": "CicloPlus ની મૂળ સુવિધાઓ હંમેશા મફત છે. પ્રીમિયમ સાથે વધુમાં:",
    "Prueba 7 días gratis": "7 દિવસ મફત અજમાવો",
    "Premium: gráfica de tu ciclo y aviso de cuándo has ovulado según tu temperatura.": "પ્રીમિયમ: તમારા ચક્રનો ગ્રાફ અને તાપમાન પ્રમાણે ઓવ્યુલેશનની જાણ.",
    "¿Olvidaste tu PIN?": "PIN ભૂલી ગયાં?",
    "No pasa nada. Quitaremos el PIN y cerraremos la sesión: vuelve a entrar con tu correo o tu cuenta de Google y lo recuperas todo, tus datos están guardados en tu cuenta. Después puedes poner un PIN nuevo.": "કંઈ વાંધો નહીં. અમે PIN હટાવી લૉગ આઉટ કરીશું: તમારા ઇમેઇલ કે Google ખાતાથી ફરી લૉગ ઇન કરો, બધું પાછું મળશે, તમારો ડેટા ખાતામાં સાચવેલો છે. પછી નવો PIN રાખી શકો.",
    "Quitar PIN y entrar de nuevo": "PIN હટાવો અને ફરી લૉગ ઇન કરો",
    "Temperatura, flujo, energía, medicación…": "તાપમાન, સ્રાવ, ઊર્જા, દવા…",
    "Mostrar siempre abierto": "હંમેશા ખુલ્લું બતાવો",
    "Se guarda en tu diario": "તમારી ડાયરીમાં સેવ થાય છે",
    "Mi ciclo es irregular": "મારું ચક્ર અનિયમિત છે",
    "Te mostramos un margen de fechas en vez de un día exacto": "ચોક્કસ દિવસને બદલે તારીખોની શ્રેણી બતાવીએ છીએ",
    "Verificación": "ચકાસણી",
    "Pico de LH el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} એ LH પીક: મોટે ભાગે આવતીકાલે ઓવ્યુલેશન થશે. આજે અને કાલે સૌથી ફળદ્રુપ દિવસો! 🌱",
    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} એ પોઝિટિવ ટેસ્ટ: મોટે ભાગે આવતીકાલે ઓવ્યુલેશન થશે. આજે અને કાલે સૌથી ફળદ્રુપ દિવસો! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "તમારા ટેસ્ટ મુજબ કદાચ આજે ઓવ્યુલેશન થાય છે. સૌથી ફળદ્રુપ દિવસ! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "તમારા ટેસ્ટ મુજબ કદાચ {} એ ઓવ્યુલેશન થયું. અમે તારીખો સુધારી 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "{} એ LH પીક: મોટે ભાગે આગામી 24–36 કલાકમાં ઓવ્યુલેશન થશે. આ તમારા સૌથી ફળદ્રુપ દિવસો છે! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "{} એ પોઝિટિવ ટેસ્ટ: ઓવ્યુલેશન ખૂબ નજીક છે. સૌથી ફળદ્રુપ દિવસો આજે અને કાલે 🌱",
