    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "જો તમને પોતાને નુકસાન પહોંચાડવાના વિચાર આવે, તો હમણાં જ કોઈની સાથે વાત કરો. તમારા દેશના ઇમરજન્સી નંબર પર ફોન કરો (યુરોપમાં 112). સ્પેનમાં 024 પર પણ મફત અને ગમે ત્યારે ફોન કરી શકો છો.",
