    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} को पॉज़िटिव टेस्ट: बहुत संभव है कल ओव्यूलेशन होगा। आज और कल आपके सबसे फ़र्टाइल दिन हैं! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "आपके टेस्ट के अनुसार शायद आज ओव्यूलेशन हो रहा है। आपका सबसे फ़र्टाइल दिन! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "आपके टेस्ट के अनुसार शायद {} को ओव्यूलेशन हुआ। हमने आपकी तारीखें ठीक कर दीं 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "{} को LH पीक: बहुत संभव है कि अगले 24–36 घंटों में ओव्यूलेशन होगा। ये आपके सबसे फ़र्टाइल दिन हैं! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "{} को पॉज़िटिव टेस्ट: ओव्यूलेशन बहुत पास है। सबसे फ़र्टाइल दिन आज और कल हैं 🌱",
