    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "अगर कई दिनों से ऐसा लग रहा है, तो किसी भरोसेमंद व्यक्ति या डॉक्टर से बात करें।",
    "No estás sola 💗": "आप अकेली नहीं हैं 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "अगर आप ख़ुद को नुकसान पहुँचाने के बारे में सोच रही हैं, तो अभी किसी से बात करें। अपने देश के आपातकालीन नंबर पर कॉल करें (यूरोप में 112)। स्पेन में आप 024 पर भी मुफ़्त और कभी भी कॉल कर सकती हैं।",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "आप जो महसूस करती हैं, वह मायने रखता है। आज सब कुछ संभालना ज़रूरी नहीं 💗",
    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "मेरे साथ गहरी साँस लें। कदम-दर-कदम, आप कर सकती हैं 🐾",
