    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "आपके {} दिन क़ज़ा बाकी हैं। मैं मदद करूँगी! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "रमज़ान से कुछ दिन पहले से एक हफ़्ते बाद तक \"आज\" में एक कार्ड।",
