    "Te avisaré unos días antes, contaré tus días de regla y te recordaré los días que te queden por recuperar.": "मैं कुछ दिन पहले बताऊँगी, आपके पीरियड के दिन गिनूँगी और बाकी क़ज़ा दिनों की याद दिलाऊँगी।",
