    "Verificación": "ಪರಿಶೀಲನೆ",
    "Pico de LH el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} ರಂದು LH ಉತ್ತುಂಗ: ಬಹುಶಃ ನಾಳೆ ಅಂಡೋತ್ಪತ್ತಿ. ಇಂದು ಮತ್ತು ನಾಳೆ ಅತ್ಯಂತ ಫಲವತ್ತಾದ ದಿನಗಳು! 🌱",
