    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "ನಿಮ್ಮ ಪರೀಕ್ಷೆಯ ಪ್ರಕಾರ ಬಹುಶಃ ಇಂದು ಅಂಡೋತ್ಪತ್ತಿ. ಅತ್ಯಂತ ಫಲವತ್ತಾದ ದಿನ! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "ನಿಮ್ಮ ಪರೀಕ್ಷೆಯ ಪ್ರಕಾರ ಬಹುಶಃ {} ರಂದು ಅಂಡೋತ್ಪತ್ತಿ ಆಗಿದೆ. ದಿನಾಂಕಗಳನ್ನು ಹೊಂದಿಸಿದ್ದೇವೆ 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "{} ರಂದು LH ಉತ್ತುಂಗ: ಮುಂದಿನ 24–36 ಗಂಟೆಗಳಲ್ಲಿ ಅಂಡೋತ್ಪತ್ತಿ ಆಗುವ ಸಾಧ್ಯತೆ ಹೆಚ್ಚು. ಇವು ನಿಮ್ಮ ಅತ್ಯಂತ ಫಲವತ್ತಾದ ದಿನಗಳು! 🌱",
