    "Premium: más ropa para Michi 👑": "പ്രീമിയം: മിച്ചിക്ക് കൂടുതൽ വസ്ത്രങ്ങൾ 👑",
    "Premium: te avisamos cuando tu test de ovulación o tu temperatura indican que vas a ovular.": "പ്രീമിയം: അണ്ഡോത്പാദന ടെസ്റ്റോ താപനിലയോ അണ്ഡോത്പാദനം അടുത്തെന്ന് കാണിക്കുമ്പോൾ അറിയിക്കും.",
