    "Avisos de fertilidad: temperatura y test de ovulación": "ഫലഭൂയിഷ്ഠത അറിയിപ്പുകൾ: താപനിലയും അണ്ഡോത്പാദന ടെസ്റ്റും",
    "Armario, retos y logros de Michi": "മിച്ചിയുടെ അലമാര, വെല്ലുവിളികൾ, ബാഡ്ജുകൾ",
    "Esto es Premium 👑": "ഇത് പ്രീമിയം ആണ് 👑",
    "Lo básico de CicloPlus es gratis para siempre. Con Premium, además:": "CicloPlus ന്റെ അടിസ്ഥാനങ്ങൾ എന്നും സൗജന്യം. പ്രീമിയത്തിൽ കൂടാതെ:",
    "Prueba 7 días gratis": "7 ദിവസം സൗജന്യമായി പരീക്ഷിക്കൂ",
    "Premium: gráfica de tu ciclo y aviso de cuándo has ovulado según tu temperatura.": "പ്രീമിയം: നിന്റെ ചക്ര ഗ്രാഫും താപനില അനുസരിച്ച് അണ്ഡോത്പാദന അറിയിപ്പും.",
    "¿Olvidaste tu PIN?": "PIN മറന്നോ?",
    "No pasa nada. Quitaremos el PIN y cerraremos la sesión: vuelve a entrar con tu correo o tu cuenta de Google y lo recuperas todo, tus datos están guardados en tu cuenta. Después puedes poner un PIN nuevo.": "കുഴപ്പമില്ല. PIN നീക്കി നിന്നെ ലോഗ് ഔട്ട് ചെയ്യും: നിന്റെ ഇമെയിൽ അല്ലെങ്കിൽ Google അക്കൗണ്ടിൽ വീണ്ടും കയറൂ, എല്ലാം തിരികെ കിട്ടും, നിന്റെ ഡാറ്റ അക്കൗണ്ടിൽ സുരക്ഷിതമാണ്. പിന്നെ പുതിയ PIN വെക്കാം.",
