    "Te mostramos un margen de fechas en vez de un día exacto": "കൃത്യ ദിവസത്തിന് പകരം തീയതി പരിധി കാണിക്കും",
    "Verificación": "സ്ഥിരീകരണം",
    "Pico de LH el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} ന് LH ഉച്ചസ്ഥായി: മിക്കവാറും നാളെ അണ്ഡോത്പാദനം. ഇന്നും നാളെയും ഏറ്റവും ഫലഭൂയിഷ്ഠമായ ദിവസങ്ങൾ! 🌱",
    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} ന് പോസിറ്റീവ് ടെസ്റ്റ്: മിക്കവാറും നാളെ അണ്ഡോത്പാദനം. ഇന്നും നാളെയും ഏറ്റവും ഫലഭൂയിഷ്ഠമായ ദിവസങ്ങൾ! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "നിന്റെ ടെസ്റ്റ് പ്രകാരം മിക്കവാറും ഇന്ന് അണ്ഡോത്പാദനം. ഏറ്റവും ഫലഭൂയിഷ്ഠമായ ദിവസം! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "നിന്റെ ടെസ്റ്റ് പ്രകാരം മിക്കവാറും {} ന് അണ്ഡോത്പാദനം നടന്നു. തീയതികൾ ശരിയാക്കി 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "{} ന് LH ഉച്ചസ്ഥായി: അടുത്ത 24–36 മണിക്കൂറിനുള്ളിൽ അണ്ഡോത്പാദനം നടക്കാൻ സാധ്യത കൂടുതലാണ്. ഇവയാണ് നിന്റെ ഏറ്റവും ഫലഭൂയിഷ്ഠമായ ദിവസങ്ങൾ! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "{} ന് പോസിറ്റീവ് ടെസ്റ്റ്: അണ്ഡോത്പാദനം വളരെ അടുത്താണ്. ഏറ്റവും ഫലഭൂയിഷ്ഠമായ ദിവസങ്ങൾ ഇന്നും നാളെയും 🌱",
