    "Apuntar la de hoy": "ഇന്നത്തേത് രേഖപ്പെടുത്തൂ",
    "Tu temperatura ha subido: probablemente ovulaste el {} 🌱": "നിന്റെ താപനില ഉയർന്നു: ഒരുപക്ഷേ {} ന് അണ്ഡോത്പാദനം നടന്നു 🌱",
    "Tu ciclo (últimos 30 registros)": "നിന്റെ ചക്രം (അവസാന 30 അളവുകൾ)",
    "La línea discontinua marca tu temperatura antes de ovular.": "കുത്തുവര അണ്ഡോത്പാദനത്തിന് മുമ്പുള്ള താപനില കാണിക്കുന്നു.",
    "Cómo medirla bien": "ശരിയായി എങ്ങനെ അളക്കാം",
    "Al despertar, antes de levantarte, hablar o beber, y siempre a la misma hora. Después de ovular sube unos 0,3 °C y se queda alta hasta la regla.": "ഉണർന്നയുടൻ, എഴുന്നേൽക്കുന്നതിനോ സംസാരിക്കുന്നതിനോ കുടിക്കുന്നതിനോ മുമ്പ്, എപ്പോഴും ഒരേ സമയത്ത്. അണ്ഡോത്പാദനത്തിന് ശേഷം ഏകദേശം 0.3 °C ഉയർന്ന് ആർത്തവം വരെ ഉയർന്നുതന്നെ നിൽക്കും.",
