    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} रोजी पॉझिटिव्ह टेस्ट: बहुधा उद्या ओव्ह्युलेशन होईल. आज आणि उद्या सर्वात सुपीक दिवस! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "तुमच्या टेस्टनुसार बहुधा आज ओव्ह्युलेशन होत आहे. सर्वात सुपीक दिवस! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "तुमच्या टेस्टनुसार बहुधा {} रोजी ओव्ह्युलेशन झाले. आम्ही तारखा जुळवल्या 🌱",
