    "Premium: gráfica de tu ciclo y aviso de cuándo has ovulado según tu temperatura.": "ပရီမီယံ: သင့်စက်ဝန်း ဂရပ်နှင့် အပူချိန်အရ မျိုးဥကြွေချိန် အသိပေးချက်။",
    "¿Olvidaste tu PIN?": "PIN မေ့သွားပြီလား?",
