    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "{} တွင် LH အမြင့်ဆုံး: နောက် 24–36 နာရီအတွင်း မျိုးဥကြွေဖွယ် များသည်။ သင့်ရဲ့ အချိန်ကောင်းဆုံးရက်များ! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "{} တွင် စမ်းသပ်ချက် အပြုသဘော: မျိုးဥကြွေချိန် အလွန်နီးပြီ။ အချိန်ကောင်းဆုံးမှာ ယနေ့နှင့် မနက်ဖြန် 🌱",
