    "Verificación": "प्रमाणीकरण",
    "Pico de LH el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} मा LH शिखर: सम्भवतः भोलि डिम्बक्षरण हुनेछ। आज र भोलि सबैभन्दा उर्वर दिन! 🌱",
    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} मा पोजिटिभ टेस्ट: सम्भवतः भोलि डिम्बक्षरण हुनेछ। आज र भोलि सबैभन्दा उर्वर दिन! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "तपाईंको टेस्टअनुसार सम्भवतः आज डिम्बक्षरण हुँदैछ। सबैभन्दा उर्वर दिन! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "तपाईंको टेस्टअनुसार सम्भवतः {} मा डिम्बक्षरण भयो। हामीले मितिहरू मिलायौं 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "{} मा LH शिखर: सम्भवतः अर्को २४–३६ घण्टामा डिम्बक्षरण हुनेछ। यी तपाईंका सबैभन्दा उर्वर दिन हुन्! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "{} मा पोजिटिभ टेस्ट: डिम्बक्षरण धेरै नजिक छ। सबैभन्दा उर्वर दिन आज र भोलि 🌱",
