    "Premium: gráfica de tu ciclo y aviso de cuándo has ovulado según tu temperatura.": "ਪ੍ਰੀਮੀਅਮ: ਤੁਹਾਡੇ ਚੱਕਰ ਦਾ ਗ੍ਰਾਫ਼ ਅਤੇ ਤਾਪਮਾਨ ਅਨੁਸਾਰ ਓਵੂਲੇਸ਼ਨ ਦੀ ਸੂਚਨਾ।",
