    "Todas tus notas juntas": "ඔබේ සියලු සටහන් එක තැනක",
    "Te avisamos para cambiarte la compresa, el tampón o la copa": "පෑඩ්, ටැම්පොන් හෝ කෝප්පය මාරු කිරීමට මතක් කරන්නම්",
    "Análisis, tendencias e informe para el médico": "විශ්ලේෂණ, ප්‍රවණතා සහ වෛද්‍යවරයාට වාර්තාව",
    "Relaciones con o sin protección": "ආරක්ෂාව සහිතව හෝ රහිතව සම්බන්ධතා",
