    "Fechas especiales, solo si quieres": "විශේෂ දින, ඔබට අවශ්‍ය නම් පමණක්",
    "Elige una opción para ver fechas especiales. Se guarda solo en tu móvil y no la recibimos.": "විශේෂ දින බැලීමට විකල්පයක් තෝරන්න. එය ඔබේ දුරකථනයේ පමණක් සුරැකේ, අපට ලැබෙන්නේ නැත.",
