    "Tu santo": "ඔබේ ශාන්තුවරයාගේ දිනය",
    "No encontramos tu santo. Elige el día.": "ඔබේ ශාන්තුවරයාගේ දිනය හමු නොවීය. දිනය තෝරන්න.",
    "Elegir día": "දිනය තෝරන්න",
    "¡Feliz santo! 🎉": "සුබ ශාන්තුවර දිනයක්! 🎉",
