    "Premium: te avisamos cuando tu test de ovulación o tu temperatura indican que vas a ovular.": "Premium: dáme ti vedieť, keď ovulačný test alebo teplota ukážu, že sa blíži ovulácia.",
    "Retos de Michi": "Michiho výzvy",
