    "Informe completo para tu médico": "Kompletná správa pre lekára",
    "Avisos de fertilidad: temperatura y test de ovulación": "Upozornenia na plodnosť: teplota a ovulačný test",
    "Armario, retos y logros de Michi": "Michiho šatník, výzvy a odznaky",
    "Esto es Premium 👑": "Toto je Premium 👑",
    "Lo básico de CicloPlus es gratis para siempre. Con Premium, además:": "Základ CicloPlus je navždy zadarmo. S Premium navyše získaš:",
    "Prueba 7 días gratis": "Vyskúšaj 7 dní zadarmo",
    "Premium: gráfica de tu ciclo y aviso de cuándo has ovulado según tu temperatura.": "Premium: graf tvojho cyklu a upozornenie, kedy si ovulovala podľa teploty.",
    "¿Olvidaste tu PIN?": "Zabudla si PIN?",
    "No pasa nada. Quitaremos el PIN y cerraremos la sesión: vuelve a entrar con tu correo o tu cuenta de Google y lo recuperas todo, tus datos están guardados en tu cuenta. Después puedes poner un PIN nuevo.": "Nevadí. Odstránime PIN a odhlásime ťa: prihlás sa znova e-mailom alebo účtom Google a všetko získaš späť, tvoje údaje sú uložené v účte. Potom si môžeš nastaviť nový PIN.",
    "Quitar PIN y entrar de nuevo": "Odstrániť PIN a prihlásiť sa znova",
    "Temperatura, flujo, energía, medicación…": "Teplota, výtok, energia, lieky…",
    "Mostrar siempre abierto": "Vždy zobraziť otvorené",
    "Se guarda en tu diario": "Uloží sa do tvojho denníka",
    "Mi ciclo es irregular": "Môj cyklus je nepravidelný",
    "Te mostramos un margen de fechas en vez de un día exacto": "Ukážeme ti rozpätie dátumov namiesto presného dňa",
    "Verificación": "Overenie",
    "Pico de LH el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "Vrchol LH {}: najskôr budeš ovulovať zajtra. Dnes a zajtra sú tvoje najplodnejšie dni! 🌱",
    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "Pozitívny test {}: najskôr budeš ovulovať zajtra. Dnes a zajtra sú tvoje najplodnejšie dni! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "Podľa ovulačného testu najskôr ovuluješ dnes. Je to tvoj najplodnejší deň! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "Podľa ovulačného testu si najskôr ovulovala {}. Upravili sme tvoje dátumy 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "Vrchol LH {}: s najväčšou pravdepodobnosťou budeš ovulovať do 24–36 hodín. Sú to tvoje najplodnejšie dni! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "Pozitívny test {}: ovulácia je veľmi blízko. Najplodnejšie dni sú dnes a zajtra 🌱",
    "Tu temperatura de hoy": "Tvoja dnešná teplota",
    "Apuntar la de hoy": "Zapísať dnešnú",
