    "Tu ciclo (últimos 30 registros)": "Tvoj cyklus (posledných 30 meraní)",
    "La línea discontinua marca tu temperatura antes de ovular.": "Prerušovaná čiara ukazuje teplotu pred ovuláciou.",
    "Cómo medirla bien": "Ako správne merať",
    "Al despertar, antes de levantarte, hablar o beber, y siempre a la misma hora. Después de ovular sube unos 0,3 °C y se queda alta hasta la regla.": "Po prebudení, skôr než vstaneš, prehovoríš alebo sa napiješ, a vždy v rovnaký čas. Po ovulácii stúpne asi o 0,3 °C a zostane vysoká až do menštruácie.",
    "¡Copia guardada en la nube! 💗": "Záloha uložená v cloude! 💗",
    "No se pudo guardar. Revisa tu conexión a internet.": "Nepodarilo sa uložiť. Skontroluj pripojenie na internet.",
