    "Te enviaremos un correo a {} para que pongas una contraseña nueva.": "Pošleme ti e-mail na {}, aby si si mohla nastaviť nové heslo.",
    "Enviar correo": "Odoslať e-mail",
    "Correo enviado. Mira tu bandeja de entrada (y la carpeta de spam).": "E-mail odoslaný. Pozri si doručenú poštu (aj spam).",
