    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "Kipimo chanya tarehe {}: ovulesheni iko karibu sana. Siku zenye rutuba zaidi ni leo na kesho 🌱",
