  "ta": {
    "Duración del ciclo (últimos 3)": "சுழற்சி நீளம் (கடைசி 3)",
    "Premium: historial completo de tus ciclos, síntomas y estado de ánimo.": "பிரீமியம்: உங்கள் சுழற்சிகள், அறிகுறிகள், மனநிலையின் முழு வரலாறு.",
    "Premium: toca una tendencia para ver su detalle de 8 semanas.": "பிரீமியம்: 8 வார விவரத்தைக் காண ஒரு போக்கைத் தட்டவும்.",
    "Premium: más ropa para Michi 👑": "பிரீமியம்: மிச்சிக்கு மேலும் உடைகள் 👑",
    "Premium: te avisamos cuando tu test de ovulación o tu temperatura indican que vas a ovular.": "பிரீமியம்: அண்டவிடுப்பு சோதனை அல்லது வெப்பநிலை அண்டவிடுப்பு நெருங்குவதைக் காட்டும்போது தெரிவிப்போம்.",
    "Retos de Michi": "மிச்சியின் சவால்கள்",
    "Análisis del ciclo y tendencias": "சுழற்சி பகுப்பாய்வு மற்றும் போக்குகள்",
    "Informe completo para tu médico": "மருத்துவருக்கு முழு அறிக்கை",
    "Avisos de fertilidad: temperatura y test de ovulación": "கருவுறுதல் எச்சரிக்கைகள்: வெப்பநிலை மற்றும் அண்டவிடுப்பு சோதனை",
    "Armario, retos y logros de Michi": "மிச்சியின் அலமாரி, சவால்கள் மற்றும் பதக்கங்கள்",
    "Esto es Premium 👑": "இது பிரீமியம் 👑",
    "Lo básico de CicloPlus es gratis para siempre. Con Premium, además:": "CicloPlus இன் அடிப்படைகள் எப்போதும் இலவசம். பிரீமியத்தில் கூடுதலாக:",
    "Prueba 7 días gratis": "7 நாட்கள் இலவசமாக முயற்சி",
    "Premium: gráfica de tu ciclo y aviso de cuándo has ovulado según tu temperatura.": "பிரீமியம்: உங்கள் சுழற்சி வரைபடம் மற்றும் வெப்பநிலைப்படி அண்டவிடுப்பு அறிவிப்பு.",
    "¿Olvidaste tu PIN?": "PIN மறந்துவிட்டதா?",
    "No pasa nada. Quitaremos el PIN y cerraremos la sesión: vuelve a entrar con tu correo o tu cuenta de Google y lo recuperas todo, tus datos están guardados en tu cuenta. Después puedes poner un PIN nuevo.": "பரவாயில்லை. PIN-ஐ நீக்கி உங்களை வெளியேற்றுவோம்: உங்கள் மின்னஞ்சல் அல்லது Google கணக்கில் மீண்டும் உள்நுழையுங்கள், எல்லாம் திரும்ப கிடைக்கும், உங்கள் தரவு கணக்கில் சேமிக்கப்பட்டுள்ளது. பிறகு புதிய PIN வைக்கலாம்.",
    "Quitar PIN y entrar de nuevo": "PIN-ஐ நீக்கி மீண்டும் உள்நுழை",
    "Temperatura, flujo, energía, medicación…": "வெப்பநிலை, சுரப்பு, ஆற்றல், மருந்து…",
    "Mostrar siempre abierto": "எப்போதும் திறந்தே காட்டு",
    "Se guarda en tu diario": "உங்கள் டைரியில் சேமிக்கப்படும்",
    "Mi ciclo es irregular": "என் சுழற்சி ஒழுங்கற்றது",
    "Te mostramos un margen de fechas en vez de un día exacto": "சரியான நாளுக்குப் பதில் தேதி வரம்பைக் காட்டுவோம்",
    "Verificación": "சரிபார்ப்பு",
    "Pico de LH el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} அன்று LH உச்சம்: பெரும்பாலும் நாளை அண்டவிடுப்பு. இன்றும் நாளையும் மிகக் கருவுறும் நாட்கள்! 🌱",
    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} அன்று பாசிட்டிவ் சோதனை: பெரும்பாலும் நாளை அண்டவிடுப்பு. இன்றும் நாளையும் மிகக் கருவுறும் நாட்கள்! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "உங்கள் சோதனைப்படி பெரும்பாலும் இன்று அண்டவிடுப்பு. மிகக் கருவுறும் நாள்! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "உங்கள் சோதனைப்படி பெரும்பாலும் {} அன்று அண்டவிடுப்பு நடந்தது. தேதிகளைச் சரிசெய்தோம் 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "{} அன்று LH உச்சம்: அடுத்த 24–36 மணி நேரத்தில் அண்டவிடுப்பு நடக்க வாய்ப்பு அதிகம். இவை உங்கள் மிகக் கருவுறும் நாட்கள்! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "{} அன்று பாசிட்டிவ் சோதனை: அண்டவிடுப்பு மிக அருகில். மிகக் கருவுறும் நாட்கள் இன்றும் நாளையும் 🌱",
    "Tu temperatura de hoy": "இன்றைய உங்கள் வெப்பநிலை",
    "Apuntar la de hoy": "இன்றையதைப் பதிவு செய்",
    "Tu temperatura ha subido: probablemente ovulaste el {} 🌱": "உங்கள் வெப்பநிலை உயர்ந்துள்ளது: {} அன்று அண்டவிடுப்பு நடந்திருக்கலாம் 🌱",
    "Tu ciclo (últimos 30 registros)": "உங்கள் சுழற்சி (கடைசி 30 அளவீடுகள்)",
    "La línea discontinua marca tu temperatura antes de ovular.": "புள்ளிக்கோடு அண்டவிடுப்புக்கு முந்தைய வெப்பநிலையைக் காட்டுகிறது.",
    "Cómo medirla bien": "சரியாக அளப்பது எப்படி",
    "Al despertar, antes de levantarte, hablar o beber, y siempre a la misma hora. Después de ovular sube unos 0,3 °C y se queda alta hasta la regla.": "எழுந்ததும், படுக்கையிலிருந்து எழுவதற்கு, பேசுவதற்கு அல்லது குடிப்பதற்கு முன், எப்போதும் ஒரே நேரத்தில். அண்டவிடுப்புக்குப் பின் சுமார் 0.3 °C உயர்ந்து மாதவிடாய் வரை உயர்ந்தே இருக்கும்.",
    "¡Copia guardada en la nube! 💗": "நகல் கிளவுடில் சேமிக்கப்பட்டது! 💗",
    "No se pudo guardar. Revisa tu conexión a internet.": "சேமிக்க முடியவில்லை. இணைய இணைப்பைச் சரிபார்க்கவும்.",
    "Cambiar contraseña": "கடவுச்சொல்லை மாற்று",
    "Te enviaremos un correo a {} para que pongas una contraseña nueva.": "புதிய கடவுச்சொல் அமைக்க {} க்கு மின்னஞ்சல் அனுப்புவோம்.",
    "Enviar correo": "மின்னஞ்சல் அனுப்பு",
