    "Premium: te avisamos cuando tu test de ovulación o tu temperatura indican que vas a ovular.": "ప్రీమియం: అండోత్సర్గ టెస్ట్ లేదా ఉష్ణోగ్రత అండోత్సర్గం దగ్గర్లో ఉందని చూపినప్పుడు మేం తెలియజేస్తాం.",
