    "Premium: gráfica de tu ciclo y aviso de cuándo has ovulado según tu temperatura.": "ప్రీమియం: మీ చక్ర గ్రాఫ్ మరియు ఉష్ణోగ్రత ప్రకారం అండోత్సర్గ సమాచారం.",
