    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "ผลตรวจเป็นบวกวันที่ {}: มีแนวโน้มไข่ตกพรุ่งนี้ วันนี้และพรุ่งนี้เป็นวันที่เจริญพันธุ์ที่สุด! 🌱",
