    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "ผลตรวจเป็นบวกวันที่ {}: ใกล้ไข่ตกมากแล้ว วันที่เจริญพันธุ์ที่สุดคือวันนี้และพรุ่งนี้ 🌱",
