    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "Yumurtlama testine göre büyük olasılıkla {} tarihinde yumurtladın. Tarihlerini güncelledik 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "{} tarihinde LH zirvesi: büyük olasılıkla 24–36 saat içinde yumurtlayacaksın. En doğurgan günlerin! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "{} tarihinde pozitif test: yumurtlaman çok yakın. En doğurgan günlerin bugün ve yarın 🌱",
