    "Verificación": "Підтвердження",
    "Pico de LH el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "Пік ЛГ {}: найімовірніше, овуляція буде завтра. Сьогодні й завтра — твої найфертильніші дні! 🌱",
    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "Позитивний тест {}: найімовірніше, овуляція буде завтра. Сьогодні й завтра — твої найфертильніші дні! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "За твоїм тестом, найімовірніше, овуляція сьогодні. Це твій найфертильніший день! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "За твоїм тестом, овуляція, найімовірніше, була {}. Ми вже поправили твої дати 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "Пік ЛГ {}: найімовірніше, овуляція буде протягом 24–36 годин. Це твої найфертильніші дні! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "Позитивний тест {}: овуляція зовсім близько. Найфертильніші дні — сьогодні й завтра 🌱",
