    "Al despertar, antes de levantarte, hablar o beber, y siempre a la misma hora. Después de ovular sube unos 0,3 °C y se queda alta hasta la regla.": "Одразу після пробудження, не встаючи, не говорячи й не п’ючи, завжди в один і той самий час. Після овуляції вона піднімається приблизно на 0,3 °C і тримається до місячних.",
