    "Pico de LH el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} kuni LH cho‘qqisi: katta ehtimol bilan ertaga ovulyatsiya bo‘ladi. Bugun va ertaga eng unumdor kunlaringiz! 🌱",
    "Test positivo el {}: lo más probable es que ovules mañana. ¡Hoy y mañana son tus días más fértiles! 🌱": "{} kuni ijobiy test: katta ehtimol bilan ertaga ovulyatsiya bo‘ladi. Bugun va ertaga eng unumdor kunlaringiz! 🌱",
    "Por tu test de ovulación, lo más probable es que ovules hoy. ¡Es tu día más fértil! 🌱": "Testingizga ko‘ra, ehtimol bugun ovulyatsiya bo‘lmoqda. Eng unumdor kuningiz! 🌱",
    "Por tu test de ovulación, lo más probable es que ovularas el {}. Ya hemos ajustado tus fechas 🌱": "Testingizga ko‘ra, ehtimol {} kuni ovulyatsiya bo‘lgan. Sanalaringizni moslashtirdik 🌱",
    "Pico de LH el {}: lo más probable es que ovules en las próximas 24–36 horas. ¡Son tus días más fértiles! 🌱": "{} kuni LH cho‘qqisi: katta ehtimol bilan 24–36 soat ichida ovulyatsiya bo‘ladi. Eng unumdor kunlaringiz! 🌱",
    "Test positivo el {}: tu ovulación está muy cerca. Tus días más fértiles son hoy y mañana 🌱": "{} kuni ijobiy test: ovulyatsiya juda yaqin. Eng unumdor kunlar — bugun va ertaga 🌱",
