    "Cómo medirla bien": "To‘g‘ri o‘lchash",
    "Al despertar, antes de levantarte, hablar o beber, y siempre a la misma hora. Después de ovular sube unos 0,3 °C y se queda alta hasta la regla.": "Uyg‘onganda, turmasdan, gapirmasdan va ichmasdan, doim bir vaqtda. Ovulyatsiyadan keyin taxminan 0,3 °C ko‘tariladi va hayzgacha baland qoladi.",
